export const isNative=()=>typeof window!=='undefined'&&!!window.BookWizHost;
function nativeFailure(error,fallback){const message=error?.message||fallback;window.dispatchEvent(new CustomEvent('bookwiz-native-error',{detail:message}));}
// A bridge may throw before returning a promise (for example when its view closes).
// Keep that failure inside the native action, including FileReader callbacks.
export function saveNative(name,blob){const host=globalThis.window?.BookWizHost;if(typeof host?.saveFile!=='function')return false;const reader=new FileReader();reader.onload=()=>{try{Promise.resolve(host.saveFile({name,mime:blob.type||'application/octet-stream',base64:String(reader.result).split(',')[1]})).catch(e=>nativeFailure(e,'The file could not be saved.'));}catch(e){nativeFailure(e,'The file could not be saved.');}};reader.onerror=()=>nativeFailure(null,'The file could not be prepared for saving.');try{reader.readAsDataURL(blob);}catch(e){nativeFailure(e,'The file could not be prepared for saving.');}return true;}
export function printNative(html,options={}){const host=globalThis.window?.BookWizHost;if(typeof host?.printHTML!=='function')return false;try{Promise.resolve(host.printHTML(html,options)).catch(e=>nativeFailure(e,'The native print view could not open.'));}catch(e){nativeFailure(e,'The native print view could not open.');}return true;}
let statsTimer;
export function syncCompanion(stats){const host=globalThis.window?.BookWizHost;if(typeof host?.updateStats!=='function')return;clearTimeout(statsTimer);statsTimer=setTimeout(()=>{try{Promise.resolve(host.updateStats(stats)).catch(e=>nativeFailure(e,'Watch progress could not refresh.'));}catch(e){nativeFailure(e,'Watch progress could not refresh.');}},800);statsTimer.unref?.();}

const printFonts=new Map();
export async function prepareNativePrintHTML(html){for(const name of ['lora.ttf','dm-sans.ttf','literata.ttf','source-serif.ttf','ibm-plex.ttf','book-arabic.ttf','book-devanagari.ttf','book-bengali.ttf']){const url=new URL('assets/'+name,import.meta.url).href;if(!html.includes(url))continue;let font=printFonts.get(name);if(!font){font=(async()=>{const response=await fetch(url);if(!response.ok)throw Error('A bundled typesetting font could not be read. Try PDF export again.');const bytes=new Uint8Array(await response.arrayBuffer());let text='';for(let i=0;i<bytes.length;i+=32768)text+=String.fromCharCode(...bytes.subarray(i,i+32768));return 'data:font/ttf;base64,'+btoa(text);})();printFonts.set(name,font);font.catch(()=>printFonts.delete(name));}html=html.replaceAll(url,await font);}return html;}
